<?php
if($action!=='bind-code')return;if($method!=='POST')Database::errorResponse('Method Not Allowed',405);$code=trim($input['code']??'');if($code===''||strlen($code)>32)Database::errorResponse('Invalid referral code',422);
$pdo=Database::getConnection();try{$pdo->beginTransaction();$refs=Database::fetchAll('SELECT id,username,referral_code,status FROM users WHERE referral_code=?',[$code]);if(count($refs)!==1)throw new RuntimeException('Referral code is missing or ambiguous');$ref=$refs[0];if($ref['id']===$userId)throw new RuntimeException('Self referral is not allowed');$ids=[$userId,$ref['id']];sort($ids,SORT_STRING);foreach($ids as $id)Database::fetchOne('SELECT id FROM users WHERE id=? FOR UPDATE',[$id]);$member=Database::fetchOne('SELECT id,username,phone,status FROM users WHERE id=?',[$userId]);if(!$member||$member['status']!=='active'||$ref['status']!=='active')throw new RuntimeException('Active accounts required');if(Database::fetchOne('SELECT id FROM referrals WHERE referred_user_id=?',[$userId]))throw new RuntimeException('A referral is already bound');$seen=[$userId=>true];$cursor=$ref['id'];for($step=0;$step<100;$step++){if(isset($seen[$cursor]))throw new RuntimeException('Referral cycle rejected');$seen[$cursor]=true;$parent=Database::fetchOne('SELECT referrer_id FROM referrals WHERE referred_user_id=?',[$cursor]);if(!$parent){$cursor='';break;}$cursor=$parent['referrer_id'];}if($cursor!=='')throw new RuntimeException('Referral chain cannot be verified');$row=['id'=>'ref-'.bin2hex(random_bytes(12)),'referrer_id'=>$ref['id'],'referrer_username'=>$ref['username'],'referrer_code'=>$code,'referred_user_id'=>$member['id'],'referred_username'=>$member['username'],'referred_phone'=>$member['phone'],'level'=>1,'instant_bonus_paid'=>0,'instant_bonus_amount'=>0,'total_deposit'=>0,'total_bet'=>0,'deposit_commission'=>0,'bet_commission'=>0,'total_commission_earned'=>0,'status'=>'pending','joined_at'=>date('Y-m-d H:i:s')];Database::insert('referrals',$row);$saved=Database::fetchOne('SELECT referrer_id FROM referrals WHERE referred_user_id=?',[$userId]);if(!$saved||$saved['referrer_id']!==$ref['id'])throw new RuntimeException('Referral persistence failed');$pdo->commit();Database::jsonResponse(['success'=>true,'message'=>'রেফারেল কোড সংরক্ষিত হয়েছে।']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();Database::errorResponse($e instanceof RuntimeException&&!($e instanceof PDOException)?$e->getMessage():'Referral could not be saved',400);}
